#### REQ-INT-004-001: Transformation Architecture Pattern

**Status**: Recommended
**Rationale**: Establish consistent transformation architecture with composable transformers

**Requirements**:
- Define `ITransformer<TInput, TOutput>` interface for all transformation logic
- Implement transformation pipelines that chain multiple transformers
- Register transformers in DI container with appropriate lifetimes
- Support synchronous and asynchronous transformation operations
- Implement transformation error handling with DLQ publishing
- Use factory pattern for dynamic transformer selection based on event type

**Implementation**:
```csharp
// Core transformation interface
public interface ITransformer<in TInput, TOutput>
{
    Task<TOutput> TransformAsync(TInput input, CancellationToken cancellationToken = default);
}

// Transformation pipeline builder
public class TransformationPipeline<TInput, TOutput>
{
    private readonly List<Func<object, Task<object>>> _transformers = new();

    public TransformationPipeline<TIntermediate, TOutput> Then<TIntermediate>(
        ITransformer<TInput, TIntermediate> transformer)
    {
        var pipeline = new TransformationPipeline<TIntermediate, TOutput>();
        pipeline._transformers.AddRange(_transformers);
        pipeline._transformers.Add(async input =>
            await transformer.TransformAsync((TInput)input, default));
        return pipeline;
    }

    public async Task<TOutput> ExecuteAsync(TInput input, CancellationToken cancellationToken = default)
    {
        object current = input;
        foreach (var transformer in _transformers)
        {
            current = await transformer(current);
        }
        return (TOutput)current;
    }
}

// DI registration
public static class TransformationServiceExtensions
{
    public static IServiceCollection AddTransformers(this IServiceCollection services)
    {
        services.AddScoped<ITransformer<ExternalClaimEvent, InternalClaimEvent>, ClaimMappingTransformer>();
        services.AddScoped<ITransformer<InternalClaimEvent, EnrichedClaimEvent>, ClaimEnrichmentTransformer>();
        services.AddScoped<ITransformer<EnrichedClaimEvent, RoutedClaimEvent>, ClaimRoutingTransformer>();

        // Transformation factory
        services.AddSingleton<ITransformerFactory, TransformerFactory>();

        return services;
    }
}

// Factory for dynamic transformer selection
public interface ITransformerFactory
{
    ITransformer<TInput, TOutput> GetTransformer<TInput, TOutput>(string eventType);
}

public class TransformerFactory : ITransformerFactory
{
    private readonly IServiceProvider _serviceProvider;
    private readonly Dictionary<(Type, Type, string), Type> _transformerMap = new();

    public TransformerFactory(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
        RegisterTransformers();
    }

    private void RegisterTransformers()
    {
        _transformerMap[(typeof(ExternalClaimEvent), typeof(InternalClaimEvent), "claim")] =
            typeof(ClaimMappingTransformer);
        _transformerMap[(typeof(ExternalPatientEvent), typeof(InternalPatientEvent), "patient")] =
            typeof(PatientMappingTransformer);
    }

    public ITransformer<TInput, TOutput> GetTransformer<TInput, TOutput>(string eventType)
    {
        if (_transformerMap.TryGetValue((typeof(TInput), typeof(TOutput), eventType), out var transformerType))
        {
            return (ITransformer<TInput, TOutput>)_serviceProvider.GetRequiredService(transformerType);
        }
        throw new InvalidOperationException($"No transformer found for {eventType}");
    }
}
```

