#### REQ-INT-004-002: Event Mapping with AutoMapper

**Status**: Recommended
**Rationale**: Use AutoMapper for declarative event-to-event schema mapping

**Requirements**:
- Use AutoMapper >= 12.0.0 for event mapping configuration
- Define mapping profiles per bounded context or event category
- Implement custom value resolvers for complex transformations
- Use `ForMember()` for explicit property mappings to avoid convention errors
- Validate mappings at application startup with `AssertConfigurationIsValid()`
- Support conditional mapping based on source event properties

**Implementation**:
```csharp
// AutoMapper profile for claim events
public class ClaimEventMappingProfile : Profile
{
    public ClaimEventMappingProfile()
    {
        // External to internal claim mapping
        CreateMap<ExternalClaimEvent, InternalClaimEvent>()
            .ForMember(dest => dest.ClaimId, opt => opt.MapFrom(src => src.ExternalClaimId))
            .ForMember(dest => dest.ClaimAmount, opt => opt.MapFrom<ClaimAmountResolver>())
            .ForMember(dest => dest.ServiceDate, opt => opt.MapFrom(src =>
                DateTime.Parse(src.ServiceDateString)))
            .ForMember(dest => dest.PatientId, opt => opt.MapFrom(src => src.Patient.Id))
            .ForMember(dest => dest.ProviderId, opt => opt.MapFrom(src => src.Provider.TaxId))
            .ForMember(dest => dest.Status, opt => opt.MapFrom(src =>
                Enum.Parse<ClaimStatus>(src.StatusCode)))
            .ForMember(dest => dest.TransformedAt, opt => opt.MapFrom(src => DateTime.UtcNow));

        // Conditional mapping based on claim type
        CreateMap<ExternalClaimEvent, ProfessionalClaimEvent>()
            .IncludeBase<ExternalClaimEvent, InternalClaimEvent>()
            .ForMember(dest => dest.PlaceOfService, opt => opt.MapFrom(src => src.PosCode))
            .ForMember(dest => dest.DiagnosisCodes, opt => opt.MapFrom(src => src.DiagnosisPointers));

        CreateMap<ExternalClaimEvent, InstitutionalClaimEvent>()
            .IncludeBase<ExternalClaimEvent, InternalClaimEvent>()
            .ForMember(dest => dest.BillType, opt => opt.MapFrom(src => src.TypeOfBill))
            .ForMember(dest => dest.AdmissionDate, opt => opt.MapFrom(src =>
                DateTime.Parse(src.AdmitDateString)));
    }
}

// Custom value resolver for complex amount calculation
public class ClaimAmountResolver : IValueResolver<ExternalClaimEvent, InternalClaimEvent, decimal>
{
    public decimal Resolve(ExternalClaimEvent source, InternalClaimEvent destination,
        decimal destMember, ResolutionContext context)
    {
        // Complex calculation from multiple source properties
        var billedAmount = decimal.Parse(source.BilledAmountString);
        var discount = source.DiscountPercentage / 100m;
        return billedAmount * (1 - discount);
    }
}

// Mapping transformer using AutoMapper
public class ClaimMappingTransformer : ITransformer<ExternalClaimEvent, InternalClaimEvent>
{
    private readonly IMapper _mapper;
    private readonly ILogger<ClaimMappingTransformer> _logger;

    public ClaimMappingTransformer(IMapper mapper, ILogger<ClaimMappingTransformer> logger)
    {
        _mapper = mapper;
        _logger = logger;
    }

    public async Task<InternalClaimEvent> TransformAsync(ExternalClaimEvent input,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Determine target type based on claim type
            var targetEvent = input.ClaimTypeCode switch
            {
                "PROF" => _mapper.Map<ProfessionalClaimEvent>(input),
                "INST" => _mapper.Map<InstitutionalClaimEvent>(input),
                _ => _mapper.Map<InternalClaimEvent>(input)
            };

            _logger.LogInformation("Mapped {SourceType} to {TargetType} for claim {ClaimId}",
                input.GetType().Name, targetEvent.GetType().Name, targetEvent.ClaimId);

            return targetEvent;
        }
        catch (AutoMapperMappingException ex)
        {
            _logger.LogError(ex, "AutoMapper mapping failed for claim {ClaimId}", input.ExternalClaimId);
            throw;
        }
    }
}

// DI registration
services.AddAutoMapper(cfg =>
{
    cfg.AddProfile<ClaimEventMappingProfile>();
    cfg.AddProfile<PatientEventMappingProfile>();
    // Validate at startup
    cfg.AssertConfigurationIsValid();
});
```

