            cfg.AddProfile<PatientEventMappingProfile>();

            if (configuration.GetValue<bool>("AutoMapper:ValidateOnStartup"))
            {
                cfg.AssertConfigurationIsValid();
            }
        });

        // FluentValidation
        services.AddValidatorsFromAssemblyContaining<EnrichedClaimEventValidator>();

        // Redis caching
        var redisConnection = configuration.GetValue<string>("Redis:ConnectionString");
        services.AddSingleton<IConnectionMultiplexer>(
            ConnectionMultiplexer.Connect(redisConnection));

        services.AddMemoryCache(options =>
        {
            options.SizeLimit = 1000; // Limit cache entries
        });

        // Transformers
        services.AddScoped<ITransformer<ExternalClaimEvent, InternalClaimEvent>, ClaimMappingTransformer>();
        services.AddScoped<ITransformer<InternalClaimEvent, EnrichedClaimEvent>, ClaimEnrichmentTransformer>();
        services.AddScoped<ITransformer<EnrichedClaimEvent, RoutedClaimEvent>, ClaimRoutingTransformer>();
        services.AddScoped<ITransformer<ClaimLineItemEvent, AggregatedClaimEvent>, ClaimAggregationTransformer>();

        // Decorated with observability and resilience
        services.Decorate(typeof(ITransformer<,>), typeof(ObservableTransformer<,>));
        services.Decorate(typeof(ITransformer<,>), typeof(ResilientTransformer<,>));

        // Transformer factory
        services.AddSingleton<ITransformerFactory, TransformerFactory>();

        // Business rules (if using NRules)
        services.AddSingleton<IRulesEngine>(sp =>
        {
            var repository = new RuleRepository();
            repository.Load(x => x.From(typeof(HighValueClaimReviewRule).Assembly));
            return repository.Compile();
        });

        // OpenTelemetry
        services.AddOpenTelemetry()
            .WithMetrics(builder =>
            {
                builder
                    .AddMeter("Transformation")
                    .AddMeter("Transformation.Metrics")
                    .AddAspNetCoreInstrumentation()
                    .AddHttpClientInstrumentation()
                    .AddAWSInstrumentation()
                    .AddOtlpExporter(options =>
                    {
                        options.Endpoint = new Uri(configuration.GetValue<string>("OpenTelemetry:OtlpEndpoint"));
