                builder
                    .AddSource("Transformation")
                    .AddAspNetCoreInstrumentation()
                    .AddHttpClientInstrumentation()
                    .AddAWSInstrumentation()
                    .AddOtlpExporter();
            });

        // Activity source for distributed tracing
        services.AddSingleton(new ActivitySource("Transformation", "1.0.0"));

        // MassTransit for publishing transformed events
        services.AddMassTransit(x =>
        {
            x.UsingKafka((context, cfg) =>
            {
                cfg.Host(configuration.GetValue<string>("MassTransit:Kafka:BootstrapServers"));
