public class ClaimEnrichmentTransformer : ITransformer<InternalClaimEvent, EnrichedClaimEvent>
{
    private readonly IPatientRepository _patientRepository;
    private readonly IMemoryCache _cache;

    public async Task<EnrichedClaimEvent> TransformAsync(InternalClaimEvent input,
        CancellationToken cancellationToken = default)
    {
        var enrichedEvent = new EnrichedClaimEvent
        {
            ClaimId = input.ClaimId,
            ClaimAmount = input.ClaimAmount,
            PatientDetails = await GetPatientDetailsAsync(input.PatientId, cancellationToken)
        };

        return enrichedEvent;
    }

    private async Task<PatientDetails> GetPatientDetailsAsync(string patientId, CancellationToken cancellationToken)
    {
        return await _cache.GetOrCreateAsync($"patient:{patientId}", async entry =>
        {
            entry.SlidingExpiration = TimeSpan.FromMinutes(15);
            var patient = await _patientRepository.GetByIdAsync(patientId, cancellationToken);
            return patient?.ToDetails();
        });
    }
}
```

