public async Task<AggregatedClaimEvent> TransformAsync(ClaimLineItemEvent input,
    CancellationToken cancellationToken = default)
{
    var db = _redis.GetDatabase();
    var stateKey = $"aggregation:claim:{input.ClaimNumber}";

    var stateJson = await db.StringGetAsync(stateKey);
    ClaimAggregationState state = stateJson.IsNullOrEmpty
        ? new ClaimAggregationState { CorrelationKey = input.ClaimNumber, ... }
        : JsonSerializer.Deserialize<ClaimAggregationState>(stateJson);

    state.LineItems.Add(new ClaimLineItem { ... });

    if (state.IsComplete || DateTime.UtcNow > state.WindowEnd)
    {
        // Publish aggregated event
        await _publishEndpoint.Publish(new AggregatedClaimEvent { ... });
        await db.KeyDeleteAsync(stateKey);
        return aggregatedEvent;
    }
    else
    {
        // Save updated state
        await db.StringSetAsync(stateKey, JsonSerializer.Serialize(state),
            expiry: state.WindowEnd - DateTime.UtcNow);
        return null; // Not complete yet
    }
}
```

