public class EnrichedClaimEventValidator : AbstractValidator<EnrichedClaimEvent>
{
    public EnrichedClaimEventValidator()
    {
        RuleFor(x => x.ClaimId).NotEmpty().MaximumLength(50);
        RuleFor(x => x.ClaimAmount).GreaterThan(0).LessThan(1000000);
        RuleFor(x => x.PatientDetails).NotNull()
            .ChildRules(patient => {
                patient.RuleFor(p => p.Name).NotEmpty();
                patient.RuleFor(p => p.DateOfBirth).LessThan(DateTime.UtcNow);
            });
    }
}
