public class ResilientTransformer<TInput, TOutput> : ITransformer<TInput, TOutput>
{
    public async Task<TOutput> TransformAsync(TInput input, CancellationToken cancellationToken = default)
    {
        try
        {
            return await _innerTransformer.TransformAsync(input, cancellationToken);
        }
        catch (ValidationException vex)
        {
            _logger.LogWarning(vex, "Validation failed");
            await PublishValidationErrorAsync(input, vex, cancellationToken);
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Transformation failed. Input: {Input}", JsonSerializer.Serialize(input));
            await PublishToDlqAsync(input, ex, cancellationToken);
            throw;
        }
    }
}
