### 4.9 Observability

**OpenTelemetry Instrumentation**:
```csharp
public class ObservableTransformer<TInput, TOutput> : ITransformer<TInput, TOutput>
{
    public async Task<TOutput> TransformAsync(TInput input, CancellationToken cancellationToken = default)
    {
        using var activity = _activitySource.StartActivity($"Transform {typeof(TInput).Name} -> {typeof(TOutput).Name}");
        activity?.SetTag("transformer.type", _innerTransformer.GetType().Name);

        var stopwatch = Stopwatch.StartNew();
        var tags = new TagList { { "transformer_type", _innerTransformer.GetType().Name } };

        try
        {
            var result = await _innerTransformer.TransformAsync(input, cancellationToken);
            stopwatch.Stop();

            tags.Add("status", "success");
            _transformationCounter.Add(1, tags);
            _transformationDuration.Record(stopwatch.Elapsed.TotalMilliseconds, tags);

            activity?.SetStatus(ActivityStatusCode.Ok);
            return result;
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            tags.Add("status", "error");
            tags.Add("error_type", ex.GetType().Name);

            _transformationCounter.Add(1, tags);
            _transformationDuration.Record(stopwatch.Elapsed.TotalMilliseconds, tags);

            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);
            throw;
        }
    }
}
```

