### 4.10 Stateful Transformations with Streamiz.Kafka.Net

**Aggregation Topology**:
```csharp
public class ClaimAggregationTopology
{
    public static Topology Build()
    {
        var builder = new StreamsBuilder();

        var claimLines = builder.Stream<string, ClaimLineItemEvent>("claim-line-items");

        claimLines
            .GroupByKey()
            .WindowedBy(TumblingWindowOptions.Of(TimeSpan.FromMinutes(5)))
            .Aggregate(
                () => new ClaimAggregation { LineItems = new List<ClaimLineItemEvent>(), TotalAmount = 0 },
                (key, lineItem, agg) => {
                    agg.LineItems.Add(lineItem);
                    agg.TotalAmount += lineItem.Amount;
                    return agg;
                },
                Materialized<string, ClaimAggregation, IWindowStore<Bytes, byte[]>>
                    .Create("claim-aggregations-store"))
            .ToStream((windowedKey, value) => windowedKey.Key)
            .MapValues(agg => new AggregatedClaimEvent {
                ClaimNumber = agg.LineItems.First().ClaimNumber,
                TotalAmount = agg.TotalAmount,
                AggregatedAt = DateTime.UtcNow
            })
            .To("aggregated-claims");

        return builder.Build();
    }
}
```

